INSERT INTO order_items
(id, order_id, product_id, quantity, unit_price, subtotal, seller_id, item_sequence,
 freight_value, discount_value, line_subtotal, line_amount, line_total, shipping_limit_at)
SELECT
    gen_random_uuid(),
    o.id,
    p.id,
    2,
    420000,
    840000,
    s.id,
    1,
    13000,
    0,
    840000,
    840000,
    853000,
    TIMESTAMPTZ '2025-09-06 19:31:14+07'
FROM orders o
JOIN products p ON p.source_product_id = 'SP019'
LEFT JOIN sellers s ON s.seller_code = 'NCC0019'
WHERE o.source_order_id = 'DH00001'
  AND NOT EXISTS (
      SELECT 1 FROM order_items oi
      WHERE oi.order_id = o.id
        AND oi.item_sequence = 1
  );

