(id, order_id, payment_sequence, payment_type, payment_method, payment_installments, payment_value, currency)
SELECT
    gen_random_uuid(),
    o.id,
    1,
    'bank_transfer',
    'Chuyển khoản',
    1,
    3441000,
    'VND'
FROM orders o
WHERE o.source_order_id = 'DH00001'
ON CONFLICT (order_id, payment_sequence) DO NOTHING;

