-- ==================== PHASE-1 CONFIGURATION ====================

INSERT INTO configuration_versions
(id, version, status, description, effective_from)
VALUES (
    gen_random_uuid(),
    'DATASET-RULE-V1',
    'ACTIVE',
    'Seeded from dataset.xlsx Phase-1 rule-based analytics',
    TIMESTAMPTZ '2026-08-13 00:00:00+07'
)
ON CONFLICT (version) DO NOTHING;

INSERT INTO scoring_rules (id, configuration_version_id, component, weight, enabled)
SELECT gen_random_uuid(), cv.id, x.component, x.weight, TRUE
FROM configuration_versions cv
CROSS JOIN (
    VALUES
        ('RECENCY',     0.35::numeric),
        ('FREQUENCY',   0.30::numeric),
        ('MONETARY',    0.20::numeric),
        ('INTERACTION', 0.15::numeric)
) AS x(component, weight)
WHERE cv.version = 'DATASET-RULE-V1'
ON CONFLICT (configuration_version_id, component)
DO UPDATE SET weight = EXCLUDED.weight, enabled = EXCLUDED.enabled;

-- Dataset valid-order behavior: only delivered orders are used for RFM.
INSERT INTO valid_order_status_configs
(id, configuration_version_id, order_status, is_valid_for_analytics)
SELECT gen_random_uuid(), cv.id, x.order_status, x.is_valid
FROM configuration_versions cv
CROSS JOIN (
    VALUES
        ('delivered', TRUE),
        ('returned', FALSE),
        ('canceled', FALSE),
        ('processing', FALSE)
) AS x(order_status, is_valid)
WHERE cv.version = 'DATASET-RULE-V1'
ON CONFLICT (configuration_version_id, order_status)
DO UPDATE SET is_valid_for_analytics = EXCLUDED.is_valid_for_analytics;

-- Replace segmentation rules for this config version to keep the script rerunnable.
DELETE FROM segmentation_rules
WHERE configuration_version_id = (
    SELECT id FROM configuration_versions WHERE version = 'DATASET-RULE-V1'
);

INSERT INTO segmentation_rules
(id, configuration_version_id, segment_code, min_potential_score, max_potential_score, priority, enabled)
SELECT gen_random_uuid(), cv.id, x.segment_code, x.min_score, x.max_score, x.priority, TRUE
FROM configuration_versions cv
CROSS JOIN (
    VALUES
        ('TIEM_NANG_CAO', 80::numeric, NULL::numeric, 30),
        ('TIEM_NANG', 60::numeric, 79.9999::numeric, 20),
        ('THONG_THUONG', NULL::numeric, 59.9999::numeric, 10)
) AS x(segment_code, min_score, max_score, priority)
WHERE cv.version = 'DATASET-RULE-V1';


