-- ==================== CUSTOMER CURRENT SNAPSHOT ====================
-- These are convenience/cache fields only. Analytics history remains the source of truth.

UPDATE customers c
SET
    total_orders = x.total_orders,
    total_spent = x.total_spent,
    avg_order_value = x.avg_order_value,
    last_purchase_date = x.last_purchase_date,
    updated_at = now()
FROM (
    SELECT
        o.customer_id,
        COUNT(*) FILTER (WHERE o.is_valid_for_rfm) AS total_orders,
        COALESCE(SUM(o.net_amount) FILTER (WHERE o.is_valid_for_rfm), 0) AS total_spent,
        CASE
            WHEN COUNT(*) FILTER (WHERE o.is_valid_for_rfm) = 0 THEN 0
            ELSE COALESCE(SUM(o.net_amount) FILTER (WHERE o.is_valid_for_rfm), 0)
                 / COUNT(*) FILTER (WHERE o.is_valid_for_rfm)
        END AS avg_order_value,
        MAX(o.order_date) FILTER (WHERE o.is_valid_for_rfm) AS last_purchase_date
    FROM orders o
    GROUP BY o.customer_id
) x
WHERE c.id = x.customer_id;

COMMIT;

